const ponds = $input.all();
let allSensorReadings = [];

// IoT sensor data generation for each pond
ponds.forEach(pondData => {
  const pond = pondData.json;
  const currentTime = new Date().toISOString();

  // Calculate days since stocking for growth patterns
  const stockingDate = new Date(pond.start_stock_date);
  const daysOld = Math.floor((new Date() - stockingDate) / (1000 * 60 * 60 * 24));

  // Generate realistic IoT sensor readings with species-specific parameters
  const speciesParams = {
    tilapia: { optTemp: 28, optPH: 7.2, optOxygen: 6.5, mortRate: 3 },
    catfish: { optTemp: 30, optPH: 7.0, optOxygen: 6.0, mortRate: 4 },
    trout: { optTemp: 15, optPH: 7.5, optOxygen: 8.0, mortRate: 2 },
    bass: { optTemp: 25, optPH: 7.3, optOxygen: 7.0, mortRate: 3.5 }
  };

  const params = speciesParams[pond.fish_species] || speciesParams.tilapia;

  // Temperature sensor with realistic variations and day/night cycle
  const hourOfDay = new Date().getHours();
  const dayNightFactor = Math.sin((hourOfDay - 6) * Math.PI / 12) * 2; // Day warmer than night
  const randomVariation = (Math.random() - 0.5) * 4;
  const temperature = Math.round((params.optTemp + dayNightFactor + randomVariation) * 10) / 10;

  // pH sensor with buffer variations
  const phVariation = (Math.random() - 0.5) * 1.5;
  const phLevel = Math.round((params.optPH + phVariation) * 10) / 10;

  // Dissolved Oxygen with temperature correlation (warmer = less oxygen)
  const tempEffect = (temperature - params.optTemp) * -0.2;
  const oxygenVariation = (Math.random() - 0.5) * 2;
  const dissolvedOxygen = Math.round((params.optOxygen + tempEffect + oxygenVariation) * 10) / 10;

  // Ammonia levels (increases with fish waste over time)
  const ammoniaBase = Math.min(0.5, daysOld * 0.002 + (pond.number_of_fingerlings / 1000) * 0.1);
  const ammoniaVariation = Math.random() * 0.05;
  const ammoniaLevel = Math.round((ammoniaBase + ammoniaVariation) * 1000) / 1000;

  // Additional IoT sensors
  const turbidity = Math.round((10 + Math.random() * 20) * 10) / 10; // NTU
  const conductivity = Math.round((200 + Math.random() * 100) * 10) / 10; // μS/cm
  const waterLevel = Math.round((0.8 + Math.random() * 0.4) * 100) / 100; // meters

  // Create sensor readings array
  const sensorReadings = [
    {
      pond_id: pond.id,
      sensor_type: 'temperature',
      value: temperature,
      unit: '°C',
      device_id: `TEMP_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: temperature > 35 || temperature < 15 ? 'warning' : 'active'
    },
    {
      pond_id: pond.id,
      sensor_type: 'ph_level',
      value: phLevel,
      unit: 'pH',
      device_id: `PH_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: phLevel > 9 || phLevel < 6 ? 'warning' : 'active'
    },
    {
      pond_id: pond.id,
      sensor_type: 'dissolved_oxygen',
      value: dissolvedOxygen,
      unit: 'mg/L',
      device_id: `DO_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: dissolvedOxygen < 4 ? 'critical' : 'active'
    },
    {
      pond_id: pond.id,
      sensor_type: 'ammonia',
      value: ammoniaLevel,
      unit: 'mg/L',
      device_id: `NH3_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: ammoniaLevel > 0.3 ? 'warning' : 'active'
    },
    {
      pond_id: pond.id,
      sensor_type: 'turbidity',
      value: turbidity,
      unit: 'NTU',
      device_id: `TURB_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: 'active'
    },
    {
      pond_id: pond.id,
      sensor_type: 'conductivity',
      value: conductivity,
      unit: 'μS/cm',
      device_id: `COND_${pond.id.substring(0, 8)}`,
      timestamp: currentTime,
      status: 'active'
    }
  ];

  allSensorReadings.push(...sensorReadings);
});

return allSensorReadings.map(reading => ({ json: reading }));

const sensorData = $input.all();
let anomalies = [];
let pondAggregates = {};

// Group sensor data by pond for comprehensive analysis
sensorData.forEach(sensor => {
  const data = sensor.json;
  if (!pondAggregates[data.pond_id]) {
    pondAggregates[data.pond_id] = {};
  }
  pondAggregates[data.pond_id][data.sensor_type] = data.value;
});

// Advanced ML Anomaly Detection Algorithms
const mlAnomalyDetection = (pondId, metrics) => {
  const detectedAnomalies = [];

  // Define ML baselines (trained parameters)
  const speciesBaselines = {
    default: {
      temperature: { mean: 27.5, std: 2.5, min: 20, max: 32 },
      ph_level: { mean: 7.2, std: 0.8, min: 6.5, max: 8.5 },
      dissolved_oxygen: { mean: 6.5, std: 1.2, min: 5.0, max: 10.0 },
      ammonia: { mean: 0.1, std: 0.08, min: 0, max: 0.25 },
      turbidity: { mean: 15, std: 8, min: 5, max: 40 },
      conductivity: { mean: 250, std: 50, min: 150, max: 400 }
    }
  };

  const baseline = speciesBaselines.default;

  // ML Algorithm 1: Z-Score Anomaly Detection
  const zScoreDetection = (value, mean, std) => {
    if (std === 0) return 0;
    return Math.abs(value - mean) / std;
  };

  // ML Algorithm 2: Isolation Forest Score (simplified)
  const isolationScore = (value, min, max) => {
    const range = max - min;
    const normalizedValue = (value - min) / range;
    // Higher scores for values near extremes
    return Math.min(normalizedValue, 1 - normalizedValue) * 2;
  };

  // ML Algorithm 3: Multi-variate Correlation Analysis
  const correlationAnomaly = (temp, oxygen, ph) => {
    // Temperature-Oxygen inverse correlation (warmer = less oxygen)
    const expectedOxygen = 8 - (temp - 20) * 0.15;
    const oxygenDeviation = Math.abs(oxygen - expectedOxygen);

    // pH-Ammonia correlation (higher ammonia = higher pH)
    const expectedPH = 7.0 + (metrics.ammonia || 0.1) * 5;
    const phDeviation = Math.abs(ph - expectedPH);

    return (oxygenDeviation + phDeviation) / 2;
  };

  // Run ML algorithms on each metric
  Object.entries(metrics).forEach(([metric, value]) => {
    if (baseline[metric]) {
      const base = baseline[metric];

      // Calculate anomaly scores using multiple algorithms
      const zScore = zScoreDetection(value, base.mean, base.std);
      const isoScore = isolationScore(value, base.min, base.max);
      const corrScore = metric === 'temperature' ? 
        correlationAnomaly(value, metrics.dissolved_oxygen || 6, metrics.ph_level || 7) : 0;

      // Ensemble ML scoring (combine multiple algorithms)
      const ensembleScore = (zScore * 0.5) + (isoScore * 0.3) + (corrScore * 0.2);

      // ML confidence calculation
      const mlConfidence = Math.round(Math.min(99, Math.max(60, ensembleScore * 25)));

      // Anomaly threshold (ML decision boundary)
      if (zScore > 2.0 || ensembleScore > 1.5) {

        // ML-powered severity assessment
        let severity;
        let priority;
        if (zScore > 3.5 || ensembleScore > 2.5) {
          severity = 'critical';
          priority = 1;
        } else if (zScore > 2.5 || ensembleScore > 2.0) {
          severity = 'high';
          priority = 2;
        } else {
          severity = 'medium'; 
          priority = 3;
        }

        // ML recommendation engine
        const getMLRecommendation = (metric, value, severity) => {
          const recommendations = {
            temperature: {
              high: 'ML Alert: Temperature spike detected. Implement immediate cooling: increase water circulation, add shade cover, or introduce cool water influx.',
              low: 'ML Alert: Temperature drop detected. Check heating systems and consider thermal insulation or greenhouse covering.'
            },
            ph_level: {
              high: 'ML Alert: Alkalinity spike detected. Add organic matter (compost tea) or reduce feeding temporarily to lower pH naturally.',
              low: 'ML Alert: Acidity increase detected. Add crushed limestone or wood ash gradually. Test water source quality.'
            },
            dissolved_oxygen: {
              low: 'ML Critical: Oxygen depletion pattern detected. Emergency aeration required. Check for overcrowding and reduce feeding.'
            },
            ammonia: {
              high: 'ML Critical: Ammonia toxicity pattern detected. Immediate water change (30%) and increase biological filtration. Check for dead fish.'
            }
          };

          const direction = value > base.mean ? 'high' : 'low';
          return recommendations[metric]?.[direction] || `ML Alert: ${metric} anomaly detected. Monitor closely and consider corrective action.`;
        };

        detectedAnomalies.push({
          pond_id: pondId,
          anomaly_type: `ML_${metric.toUpperCase()}_ANOMALY`,
          metric_name: metric,
          current_value: value,
          expected_range: `${base.mean - base.std} - ${base.mean + base.std}`,
          z_score: Math.round(zScore * 100) / 100,
          isolation_score: Math.round(isoScore * 100) / 100,
          ensemble_score: Math.round(ensembleScore * 100) / 100,
          severity: severity,
          priority: priority,
          ml_confidence: mlConfidence,
          algorithm_used: 'ensemble_ml_v1.2',
          recommendation: getMLRecommendation(metric, value, severity),
          created_at: new Date().toISOString()
        });
      }
    }
  });

  return detectedAnomalies;
};

// Process each pond through ML analysis
Object.entries(pondAggregates).forEach(([pondId, metrics]) => {
  const pondAnomalies = mlAnomalyDetection(pondId, metrics);
  anomalies.push(...pondAnomalies);
});

return anomalies.map(anomaly => ({ json: anomaly }));

const anomalies = $('Advanced ML Anomaly Detection').all();
let alertsToCreate = [];

// Create intelligent alerts based on ML findings
anomalies.forEach(anomalyData => {
  const anomaly = anomalyData.json;

  // Smart alert aggregation (don't spam users)
  const alertKey = `${anomaly.pond_id}_${anomaly.metric_name}`;

  alertsToCreate.push({
    pond_id: anomaly.pond_id,
    alert_type: anomaly.anomaly_type,
    title: `🤖 AI Detection: ${anomaly.metric_name.replace('_', ' ').toUpperCase()} Anomaly`,
    message: `ML algorithms detected ${anomaly.metric_name} anomaly (${anomaly.current_value}). Confidence: ${anomaly.ml_confidence}%`,
    severity: anomaly.severity,
    priority: anomaly.priority,
    ml_generated: true,
    ml_confidence: anomaly.ml_confidence,
    algorithm_used: anomaly.algorithm_used,
    recommendation: anomaly.recommendation,
    metadata: JSON.stringify({
      z_score: anomaly.z_score,
      ensemble_score: anomaly.ensemble_score,
      expected_range: anomaly.expected_range
    }),
    created_at: new Date().toISOString(),
    status: 'active'
  });
});

return alertsToCreate.map(alert => ({ json: alert }));
